BornPersonalDialogueAccess::BornPersonalDialogueAccess(const CommonStore& c,const InteractionState& i,const BornPersonalDialogueState& s,const InteractionCatalog& d,const BornPersonalDialogueCatalog& cat,const InteractionAccess& a,const BornPersonalDialogueSources& sources):common_(c),interactions_(i),state_(s),interaction_catalog_(d),catalog_(cat),interaction_access_(a),sources_(sources){}
Outcome<BornPersonalDialogueProof> BornPersonalDialogueAccess::born_personal_dialogue(const StableId& listener,const StableId& provider,const StableId& template_id) const {
    auto valid=validate_born_personal_dialogues(common_,interactions_,state_,interaction_catalog_,catalog_,sources_);if(!valid.ok)return {false,{},valid.error};valid=validate_born_personal_dialogue_cached_results(common_,&state_);if(!valid.ok)return {false,{},valid.error};
    auto declaration=preview_authored_provider_source(common_,interactions_,interaction_catalog_,interaction_access_,listener,provider);if(!declaration.ok)return {false,{},declaration.error};
    const auto* opening=born_personal_detail::opening(state_,declaration.value.meeting.session_id);if(!opening||opening->template_id!=template_id||opening->listener_actor_id!=listener||opening->provider_actor_id!=provider||!sources_.born)return {false,{},common_failure("BornPersonalDialogueSourceRequired").error};
    auto born=sources_.born(provider);if(!born.ok)return {false,{},born.error};if(!born.value||!born_personal_detail::opening_born(*opening,*born.value)||born.value->observed_tick!=common_.tick()||!born.value->before_fact_id.empty()||!born_personal_detail::identity(born.value->source_identity,common_.state().identity))return {false,{},common_failure("BornPersonalDialogueBirthMismatch").error};
    return {true,{opening->fact_id,template_id,std::move(declaration.value),*born.value},{}};
}
Status BornPersonalDialogueAccess::born_personal_dialogue_before_fact(const BornPersonalDialogueProof& proof,Integer tick,const StableId& fact) const {
    auto valid=validate_born_personal_dialogues(common_,interactions_,state_,interaction_catalog_,catalog_,sources_);if(!valid.ok)return valid;valid=validate_born_personal_dialogue_cached_results(common_,&state_);if(!valid.ok)return valid;
    const auto* opening=state_.openings.find(proof.opening_fact_id);const auto* t=born_personal_dialogue_template(catalog_,proof.template_id);const auto& declaration=proof.declaration;const auto& m=declaration.meeting;const auto* d=t?born_personal_detail::dialogue(interaction_catalog_,t->dialogue_id):nullptr;const auto* node=d?born_personal_detail::node(*d,m.node_id):nullptr;
    if(!opening||!t||opening->template_id!=t->id||!node||node->kind!="say"||node->speaker!="$provider"||m.node_kind!="say"||m.actor_id!=opening->listener_actor_id||m.provider_actor_id!=opening->provider_actor_id||declaration.speaker_actor_id!=opening->provider_actor_id||m.session_id!=opening->session_id||m.dialogue_id!=opening->dialogue_id||m.context.place_id!=opening->place_id||m.context.provider_actor_id!=opening->provider_actor_id||!born_personal_detail::narrative(m.context)||m.source_identity.world_id!=common_.state().identity.world_id||m.source_identity.tick!=tick||m.source_identity.execution_epoch<1||m.source_identity.revision<0||m.source_identity.revision>common_.revision()||!born_personal_detail::identity(proof.born.source_identity,m.source_identity)||!proof.born.before_fact_id.empty()||proof.born.observed_tick!=tick||!born_personal_detail::opening_born(*opening,proof.born))return common_failure("InvalidBornPersonalDialogueProof",fact);
    valid=born_personal_detail::before(common_,opening->fact_id,opening->tick,fact,tick);if(!valid.ok)return valid;
    const auto committed=born_personal_detail::serial(common_,opening->player_receipt->result_id,"result"),business=born_personal_detail::serial(common_,fact);if(!committed||!business||*committed>=*business||opening->player_receipt->result_revision>m.source_identity.revision)return common_failure("BornPersonalDialogueUncommittedOpening",fact);
    auto born=sources_.born_before(opening->provider_actor_id,tick,fact);if(!born.ok)return {false,{},born.error};if(!born.value||!born_personal_detail::opening_born(*opening,*born.value)||!born_personal_detail::born_identity(*born.value,proof.born)||born.value->observed_tick!=tick||born.value->before_fact_id!=fact)return common_failure("BornPersonalDialogueBirthMismatch",fact);
    auto present=sources_.presence_before(opening->listener_actor_id,tick,fact);if(!present.ok)return {false,{},present.error};if(present.value.actor_id!=opening->listener_actor_id||present.value.before_fact_id!=fact||present.value.observed_tick!=tick||!present.value.alive)return common_failure("BornPersonalDialogueListenerAbsent",fact);
    return common_success();
}
